# when a pair of same-color dots lies on a common diagonal, the cells BETWEEN them (exclusive) become their color;
# a lone dot still paints its full 4 rays. Conflict resolution: paint in order, later paints can overwrite? or first-wins.
from collections import defaultdict,Counter
def solve(T,bg):
    H,W=len(T),len(T[0]); g=[row[:] for row in T]
    pts=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: pts[g[r][c]].append((r,c))
    for v,ps in sorted(pts.items()):
        pairs=[]
        singles=set()
        for p in ps:
            has=False
            for q in ps:
                if q!=p and ((q[0]-p[0])==(q[1]-p[1]) or (q[0]+p[0])==(q[1]+p[1])):
                    has=True; break
            if not has: singles.add(p)
        for p in singles:
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                rr,cc=p[0]+dr,p[1]+dc
                while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                    g[rr][cc]=v; rr+=dr; cc+=dc
        # pairs: fill strictly between consecutive same-color points on shared diagonal, both diag types
        for p in list(ps):
            for q in ps:
                if q>p and ((q[0]-p[0])==q[1]-p[1] or (q[0]+p[0])==q[1]+p[1]):
                    rr,cc=(p[0]+q[0])//2+0.5,(p[1]+q[1])//2+0.5
                    step=(1 if q[0]>p[0] else -1), (1 if q[1]>p[1] else -1)
                    rr,cc=p[0]+step[0],p[1]+step[1]
                    while (rr,cc)!=q:
                        if g[rr][cc]==bg: g[rr][cc]=v
                        elif g[rr][cc]!=v: break  # blocked by another color's dot / painting
                        rr+=step[0]; cc+=step[1]
    return g
