from collections import defaultdict,Counter
def solve(T,bg):
    H,W=len(T),len(T[0]); g=[row[:] for row in T]
    pts=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: pts[g[r][c]].append((r,c))
    pf={}
    for v,ps in pts.items():
        ps=list(ps)
        for i in range(len(ps)):
            for j in range(i+1,len(ps)):
                a,b=ps[i],ps[j]
                if (a[0]-b[0])!=(a[1]-b[1]) and (a[0]+b[0])!=(a[1]+b[1]): continue
                step=(1 if b[0]>a[0] else -1); sd=(1 if b[1]>a[1] else -1)
                rr,cc=a[0]+step,a[1]+sd; ok=True
                while (rr,cc)!=b:
                    if g[rr][cc]!=bg: ok=False;break
                    rr+=step; cc+=sd
                if ok:
                    rr,cc=a[0]+step,a[1]+sd
                    while (rr,cc)!=b:
                        pf[(rr,cc)]=v; rr+=step; cc+=sd
    for (r,c),vv in pf.items(): g[r][c]=vv
    def aligned(p,q):
        return (p[0]-q[0])==(p[1]-q[1]) or (p[0]+p[1])==(q[0]+q[1])
    for v,ps in pts.items():
        for p in ps:
            if any(aligned(p,q) for q in ps if q!=p): continue
            ob={k:v2 for k,v2 in pf.items()}
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                rr,cc=p[0]+dr,p[1]+dc
                while 0<=rr<H and 0<=cc<W:
                    fv=ob.get((rr,cc))
                    blocked = (g[rr][cc]!=bg) or (fv is not None and fv!=v)
                    if blocked: break
                    g[rr][cc]=v; rr+=dr; cc+=dc
    return g
